<nav class="pellet-tabs" aria-label="Espaces de pelletisation"><button type="button" data-pellet-tab="production" aria-pressed="true">Fabrication</button><button type="button" data-pellet-tab="supplies" aria-pressed="false">Approvisionnements</button><button type="button" data-pellet-tab="recipes" aria-pressed="false">Recettes</button></nav><section data-pellet-space="production"><p class="pellet-guide">1. Vérifier les matières → 2. Démarrer → 3. Saisir les résultats → 4. Valider → 5. Conditionner</p><section class="table-panel"><h3>Ordres de fabrication</h3><div class="table-responsive"><table class="enterprise-table" data-search-placeholder="Rechercher un OF, une recette ou une étape"><thead><tr><th>Lot de fabrication</th><th>Recette</th><th>Prévu (kg)</th><th>Étape</th><th>Prochaine action</th></tr></thead><tbody><?php foreach($orders as$o):?><tr data-pellet-state="<?=e($o['status'])?>"><td><?=e($o['order_number'])?></td><td><?=e($o['recipe_code'].' v'.$o['version_number'])?></td><td><?=e($o['theoretical_input_kg'])?></td><td><span class="campaign-status"><?=e($statusLabels[$o['status']]??$o['status'])?></span></td><td><?php if($o['status']==='in_progress'):?><button type="button" class="btn-primary" data-workspace-modal-open="pelletForm5-<?=e($o['id'])?>">Saisir les résultats</button><section id="pelletForm5-<?=e($o['id'])?>" class="entity-modal workspace-entity-modal feed-editor pellet-editor" role="dialog" aria-modal="true" aria-hidden="true" aria-label="Saisir les résultats"><header><div><p class="page-kicker">PELLETISATION</p><h2>Saisir les résultats</h2><p><?=e($o['order_number'])?></p></div><button type="button" class="modal-close" data-workspace-modal-close aria-label="Fermer">×</button></header><form data-pellet-form data-confirm="Confirmer : saisir les résultats ?" method="post" action="<?=e(base_url('pelletization/orders/'.$o['id'].'/results'))?>"><?=csrf_field()?><div class="feed-form-body"><p class="app-alert app-alert-error" data-feed-error hidden r