].' — '.$item['unit_capacity_kg'].' kg')?></option><?php endforeach;?></select></label><label><span>Nombre de sacs *</span><input name="bags_count" type="number" min="1" placeholder="Sacs" required></label></div><footer><button type="button" class="btn-secondary" data-workspace-modal-close>Annuler</button><button class="btn-primary">Conditionner</button></footer></form></section><?php else:?><span>Fabrication terminée</span><?php endif;?><button type="button" class="btn-secondary" data-workspace-modal-open="pelletDetail-<?=e($o['id'])?>">Consulter</button><?php require view_path('pelletization.detail');?></td></tr><?php endforeach;?></tbody></table></div></section>
